'use strict';
const $=id=>document.getElementById(id);
const modes={free:['Probador virtual','Combiná prendas y girá el modelo para ver cada detalle.',[]],daily:['Look del día','Creá un conjunto para la temática de hoy.',['casual','elegante','urbano','formal','glam','deportivo','verano','invierno']],runway:['Pasarela','Elegí el conjunto de pasarela. Usá el botón Animar para verlo en movimiento.',['glam','fiesta','elegante','formal']],duel:['Duelo de estilos','Fijá un look A, cambiá el modelo y comparalo con B.',['urbano','glam','casual','elegante']],collector:['Coleccionista','Registrá las prendas que vas descubriendo al guardar o evaluar un look.',[]],world:['Moda por el mundo','Creá un conjunto para clima y ocasión.',['verano','formal','invierno','urbano']],makeover:['Cambio de look','Acercá la cámara al rostro y probá maquillaje, pelo y expresiones.',[]],redcarpet:['Alfombra roja','Armá un conjunto de gala.',['glam','elegante','fiesta']],influencer:['Influencer Studio','Buscá el encuadre y capturá tu look.',['urbano','casual','fiesta']],atelier:['Atelier','Explorá texturas, prendas, maquillaje y colores de pelo.',[]],avatar:['Avatar libre','Ajustá la silueta, la expresión y la vestimenta sin restricciones de género.',[]],paper:['Muñeca de moda','Vestí y combiná prendas sobre el modelo tridimensional.',[]]};
let mode='free',round=0,first=null,api=null,initial=null;
function read(k){try{const v=JSON.parse(localStorage.getItem(k));return Array.isArray(v)?v:[]}catch(e){return []}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){return false}}
let saved=read('studio-style-3d-looks-v1'),seen=read('studio-style-3d-seen-v1');
const tags={casual:/casual|t-shirt|tshirt|wool_pants|shoes02/,elegante:/elegant|dress|bodice|skirt|shoes05|shoes06/,urbano:/casual|cargo|jeans|boots|t-shirt/,formal:/elegant|wool_pants|dress|polo/,glam:/dress|bodice|lace|shoes05|shoes06/,deportivo:/sport|shoes02|t-shirt/,verano:/shorts|halter|tank|camisole|mini/,invierno:/sweater|wool|boots|casualsuit05/,fiesta:/dress|lace|bodice|skirt|shoes05|shoes06/};
function theme(){let a=modes[mode][2];return a.length?a[((mode==='daily'?Math.floor(Date.now()/86400000):0)+round)%a.length]:''}
function status(t){$('status').textContent=t}
function parts(r){return [r.outfit,r.top,r.bottom,r.shoes].filter(x=>typeof x==='string'&&x)}
function score(r){const p=parts(r),test=tags[theme()];return {hits:p.filter(x=>test?.test(x)).length,total:p.length}}
function track(r){for(const id of parts(r))if(!seen.includes(id))seen.push(id);write('studio-style-3d-seen-v1',seen);$('collection').textContent='Prendas 3D descubiertas: '+seen.length}
function showMode(){const m=modes[mode];$('title').textContent=m[0];$('brief').textContent=m[1]+(theme()?' Tema: '+theme()+'.':'');$('next').hidden=!m[2].length||mode==='daily';$('evaluate').hidden=!m[2].length&&mode!=='collector';$('duel').hidden=mode!=='duel';$('duel').textContent='Fijar look A';$('comparison').hidden=true;first=null}
function recipe(){if(!api)throw Error('El motor 3D todavía no está disponible.');if(api.busy)throw Error('El conjunto todavía se está ajustando.');return structuredClone(api.recipe)}
function renderSaved(){const el=$('saved');el.replaceChildren();saved.forEach((x,i)=>{if(!x||typeof x.name!=='string'||!x.recipe)return;const row=document.createElement('div'),b=document.createElement('button'),d=document.createElement('button');b.textContent=x.name;b.disabled=!api;b.onclick=async()=>{try{api.endPreview();if(await api.applyRecipe(x.recipe)!==false)status('Look recuperado.')}catch(e){status('No se pudo cargar el look.')}};d.textContent='×';d.setAttribute('aria-label','Borrar '+x.name);d.onclick=()=>{const next=saved.filter((_,n)=>n!==i);if(write('studio-style-3d-looks-v1',next)){saved=next;renderSaved()}else status('No se pudo borrar.');};row.append(b,d);el.append(row)})}
for(const [id,m] of Object.entries(modes)){const o=document.createElement('option');o.value=id;o.textContent=m[0];$('mode').append(o)}
const requested=new URLSearchParams(location.search).get('mode');if(Object.hasOwn(modes,requested))mode=requested;$('mode').value=mode;
$('mode').onchange=()=>{mode=$('mode').value;round=0;showMode()};$('next').onclick=()=>{round++;showMode()};
$('evaluate').onclick=()=>{try{const r=recipe();track(r);const s=score(r);status(mode==='collector'?'Colección actualizada.':s.hits+' de '+s.total+' piezas coinciden con el tema '+theme()+'.')}catch(e){status(e.message)}};
$('duel').onclick=()=>{try{const r=recipe(),image=api.capture();track(r);if(!first){first={r,image};$('duel').textContent='Comparar con B';status('Look A fijado. Creá el look B.');return}const a=score(first.r),b=score(r),el=$('comparison');el.replaceChildren();for(const [label,src] of [['Look A',first.image],['Look B',image]]){const box=document.createElement('div'),p=document.createElement('p'),im=document.createElement('img');p.textContent=label;im.src=src;im.alt=label;box.append(im,p);el.append(box)}el.hidden=false;status('A: '+a.hits+'/'+a.total+' · B: '+b.hits+'/'+b.total+' · '+(a.hits===b.hits?'Empate':a.hits>b.hits?'Gana A':'Gana B')+' por coincidencias de estilo.');first=null;$('duel').textContent='Fijar look A'}catch(e){status(e.message)}};
$('save').onclick=()=>{try{if(saved.length>=20)throw Error('Máximo 20 looks. Borrá uno para seguir.');const r=recipe(),next=[...saved,{name:$('name').value.trim()||'Look '+(saved.length+1),recipe:r}];if(!write('studio-style-3d-looks-v1',next))throw Error('No se pudo guardar.');saved=next;track(r);renderSaved();status('Look guardado localmente.')}catch(e){status(e.message)}};
$('capture').onclick=()=>{try{const a=document.createElement('a');a.download='studio-look-3d.png';a.href=api.capture();a.click()}catch(e){status('No se pudo capturar.')}};
$('reset').onclick=async()=>{const b=$('reset');b.disabled=true;try{status('Reiniciando modelo y vestuario…');const ok=await api.reset();if(ok===false){status('El reinicio fue reemplazado por otro cambio.');return}first=null;$('comparison').replaceChildren();$('comparison').hidden=true;$('duel').textContent='Fijar look A';$('name').value='';status('Modelo, vestuario, cámara y expresiones reiniciados.')}catch(e){status('No se pudo reiniciar. Recargá la página.')}finally{b.disabled=false}};
showMode();renderSaved();$('collection').textContent='Prendas 3D descubiertas: '+seen.length;
const frame=$('editor');if(frame){let tries=0;const timer=setInterval(()=>{try{api=frame.contentWindow.avatarEditor;if(api){initial=recipe();clearInterval(timer);for(const id of ['evaluate','duel','save','capture','reset'])$(id).disabled=false;status('Motor 3D listo. Arrastrá el modelo para girarlo; usá la rueda para acercar.');renderSaved();return}}catch(e){}if(++tries>=120){clearInterval(timer);status('El motor 3D no terminó de cargar. Verificá WebGL y recargá la página.')}},500)}else status('Recursos 3D pendientes de publicación.');
</script></body></html>